<?php
require_once __DIR__.'/_bootstrap.php'; require_admin();
$notice='';
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') {
 verify_csrf(); $action=(string)($_POST['action']??'');
 try {
  if($action==='add_project') {
   $title=trim((string)($_POST['title']??'')); $summary=trim((string)($_POST['summary']??'')); $url=trim((string)($_POST['project_url']??'')); $stack=trim((string)($_POST['tech_stack']??''));
   if($title===''||$summary===''||mb_strlen($title)>150||mb_strlen($summary)>2000||($url!==''&&!filter_var($url,FILTER_VALIDATE_URL))) throw new RuntimeException('Check the title, summary, and project URL.');
   $slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower($title)),'-');
   $q=db()->prepare('INSERT INTO projects(title,slug,summary,tech_stack,project_url,is_published) VALUES(?,?,?,?,?,1)'); $q->execute([$title,$slug,$summary,$stack,$url?:null]); $notice='Project added.';
  } elseif($action==='delete_project') { $q=db()->prepare('DELETE FROM projects WHERE id=?'); $q->execute([(int)($_POST['id']??0)]); $notice='Project deleted.'; }
  elseif($action==='mark_read') { $q=db()->prepare('UPDATE contact_messages SET is_read=1 WHERE id=?'); $q->execute([(int)($_POST['id']??0)]); $notice='Message marked as read.'; }
 } catch(Throwable $e) { $notice=$e instanceof RuntimeException?$e->getMessage():'Action failed. Check database setup.'; error_log('Admin dashboard: '.$e->getMessage()); }
}
$projects=[];$messages=[];$counts=['projects'=>0,'messages'=>0,'unread'=>0];
try{$pdo=db();$projects=$pdo->query('SELECT id,title,summary,project_url FROM projects ORDER BY id DESC')->fetchAll();$messages=$pdo->query('SELECT id,name,email,message,created_at,is_read FROM contact_messages ORDER BY created_at DESC LIMIT 50')->fetchAll();$counts['projects']=(int)$pdo->query('SELECT COUNT(*) FROM projects')->fetchColumn();$counts['messages']=(int)$pdo->query('SELECT COUNT(*) FROM contact_messages')->fetchColumn();$counts['unread']=(int)$pdo->query('SELECT COUNT(*) FROM contact_messages WHERE is_read=0')->fetchColumn();}catch(Throwable $e){$notice='Database not ready. Import database/schema.sql and configure DB credentials.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | Vibe Coder</title><link rel="stylesheet" href="admin.css"></head><body><header class="admin-top"><a class="brand" href="../index.html">E. <span>VIBE CODER</span></a><div>Signed in as <?=h((string)($_SESSION['admin_username']??'admin'))?> · <a href="logout.php">Log out</a></div></header><main class="dashboard"><h1>Portfolio dashboard</h1><p class="muted">Manage project entries and review contact messages.</p><?php if($notice): ?><div class="notice"><?=h($notice)?></div><?php endif; ?><section class="stats"><article><b><?= $counts['projects'] ?></b><span>Projects</span></article><article><b><?= $counts['messages'] ?></b><span>Messages</span></article><article><b><?= $counts['unread'] ?></b><span>Unread</span></article></section><section class="panel"><h2>Add a project</h2><form method="post" class="project-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add_project"><label>Title<input name="title" required maxlength="150"></label><label>Project URL (optional)<input name="project_url" type="url" placeholder="https://..."></label><label>Technologies<input name="tech_stack" placeholder="HTML, CSS, PHP"></label><label class="full">Summary<textarea name="summary" required maxlength="2000" rows="3"></textarea></label><button type="submit">Add project</button></form></section><section class="panel"><h2>Projects</h2><?php if(!$projects): ?><p class="muted">No database projects yet. Existing portfolio cards remain in index.html until you choose to connect them to the API.</p><?php endif; ?><?php foreach($projects as $p): ?><div class="item"><div><strong><?=h($p['title'])?></strong><p><?=h($p['summary'])?></p></div><form method="post" onsubmit="return confirm('Delete this project entry?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_project"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="danger" type="submit">Delete</button></form></div><?php endforeach; ?></section><section class="panel"><h2>Contact messages</h2><?php if(!$messages): ?><p class="muted">No messages received yet.</p><?php endif; ?><?php foreach($messages as $m): ?><article class="message"><div class="message-head"><strong><?=h($m['name'])?></strong><span><?=h($m['email'])?> · <?=h($m['created_at'])?></span></div><p><?=nl2br(h($m['message']))?></p><?php if(!$m['is_read']): ?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="mark_read"><input type="hidden" name="id" value="<?=$m['id']?>"><button type="submit">Mark as read</button></form><?php else: ?><span class="muted">Read</span><?php endif; ?></article><?php endforeach; ?></section></main></body></html>
